'use client';

import Link from 'next/link';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { ArrowLeft, Check, Link2, Pencil, Trash2 } from 'lucide-react';
import { Header, Cover } from './Shared';

export default function BookDetail({ initialBook }) {
  const [book, setBook] = useState(initialBook);
  const [notes, setNotes] = useState(book.notes || '');
  const [editing, setEditing] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const router = useRouter();
  async function update(changes) {
    setError(''); setBusy(true);
    try {
      const response = await fetch("'`/api/books/${book.id}`, { method: '"'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(changes) });
      const result = await response.json();
      if ("'!response.ok) throw new Error(result.error);
      setBook(result); setNotes(result.notes || '"''); setEditing(false);
    } catch (error) { setError(error.message || 'Could not save changes.'); }
    finally { setBusy(false); }
  }
  async function share() {
    try { await navigator.clipboard.writeText(window.location.href); setCopied(true); setTimeout(() => setCopied(false), 2500); }
    catch { setError('Could not copy the link. You can copy it from your browser address bar.'); }
  }
  async function remove() {
    if ("'!window.confirm(`Remove “${book.title}” from your library?`)) return;
    setBusy(true); setError('"'');
    try {
      const response = await fetch("'`/api/books/${book.id}`, { method: '"'DELETE' });
      if ("'!response.ok) throw new Error('"'Could not remove this book.');
      router.push('/'); router.refresh();
    } catch (error) { setError(error.message); setBusy(false); }
  }
  return <><Header /><main className=\"detail-shell\"><Link href=\"/\" className=\"back-link\"><ArrowLeft size={16} /> Back to my library</Link>
    <div className=\"detail-grid\"><div className=\"detail-cover\"><Cover book={book} large /></div><div className=\"detail-content\">
      <p className=\"eyebrow\"><span className=\"eyebrow-line\" /> YOUR BOOKSHELF</p><div className={"'`status ${book.status === '"'reading' ? 'status-reading' : 'status-finished'}"'`}><span />{book.status === '"'reading' ? 'CURRENTLY READING' : 'FINISHED'}</div>
      <h1>{book.title}</h1><p className=\"detail-author\">by {book.author}</p>
      <div className=\"detail-actions\"><button className=\"primary-button\" disabled={busy} onClick={() => update({ status: book.status === 'reading' ? 'finished' : 'reading' })}><Check size={16} /> {book.status === 'reading' ? 'Mark as finished' : 'Mark as reading'}</button><button className=\"secondary-button\" onClick={share}><Link2 size={16} /> {copied ? 'Link copied"'!'"' : 'Copy book link'}</button></div>
      {error && <p className=\"form-error\" role=\"alert\">{error}</p>}
      <div className=\"notes-panel\"><div className=\"notes-heading\"><div><p className=\"section-kicker\">A LITTLE SOMETHING TO REMEMBER</p><h2>My notes</h2></div>{"'!editing && <button className="edit-button" onClick={() => setEditing(true)}><Pencil size={15} /> Edit notes</button>}</div>
