      </div><button className=\"remove-button\" disabled={busy} onClick={remove}><Trash2 size={15} /> Remove from library</button>
    </div></div><footer className=\"footer\"><span>Made for the stories that stay with you.</span><span>HAPPY READING <span className=\"footer-star\">✳</span></span></footer>
  </main></>;
}
