/bin/bash -lc "node --input-type=module <<'EOF'
import { writeFile } from 'node:fs/promises';
const base = 'http://localhost:3000';
const home = await fetch(base);
const html = await home.text();
if ("'!home.ok || !html.includes('"'Currently reading') || "'!html.includes('"'The Midnight Library')) throw new Error('Home page did not render library');
const created = await fetch("'`${base}/api/books`, {method:'"'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({title:'Test persistence',author:'Test Author',notes:'First note'})});
const book = await created.json();
if (created.status "'!== 201 || !book.id) throw new Error('"'Create failed');
await writeFile('/tmp/dogear-test-id',book.id);
const updated = await fetch("'`${base}/api/books/${book.id}`, {method:'"'PATCH', headers:{'content-type':'application/json'}, body:JSON.stringify({status:'finished',notes:'Updated note'})});
const result = await updated.json();
if ("'!updated.ok || result.status !== '"'finished' || result.notes "'!== '"'Updated note') throw new Error('Update failed');
const detail = await fetch("'`${base}/books/${book.id}`);
const detailHtml = await detail.text();
if (!detail.ok || !detailHtml.includes('"'Test persistence') || "'!detailHtml.includes('"'Updated note')) throw new Error('Detail failed');
const invalid = await fetch("'`${base}/api/books`, {method:'"'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:'',author:'Test'})});
if (invalid.status "'!== 400) throw new Error('"'Validation failed');
console.log('Home, create, update, detail link, and validation passed.');
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { readFile } from 'node:fs/promises';
const id = await readFile('/tmp/dogear-test-id','utf8');
const page = await fetch("'`http://localhost:3000/books/${id}`);
const html = await page.text();
if (!page.ok || !html.includes('"'Test persistence') || "'!html.includes('"'Updated note') || "'!html.includes('"'FINISHED')) throw new Error('Persistence after restart failed');
const removed = await fetch("'`http://localhost:3000/api/books/${id}`, {method:'"'DELETE'});
if ("'!removed.ok) throw new Error('"'Cleanup failed');
const missing = await fetch("'`http://localhost:3000/books/${id}`);
if (missing.status !== 404) throw new Error('"'Missing book did not return 404');
console.log('Persistence after restart, removal, and missing book passed.');
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
const base = 'http://localhost:3000';
