if (invalid.status "'!== 400) throw new Error('"'Invalid body should be rejected');
const make = i => fetch("'`${base}/api/books`, {method:'"'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title:"'`Concurrent test ${i}`,author:'"'Test'})}).then(async r => { if ("'!r.ok) throw new Error('"'create failed'); return r.json(); });
const created = await Promise.all(Array.from({length:5},(_,i)=>make(i)));
const home = await (await fetch(base)).text();
if ("'!created.every(book => home.includes(book.title))) throw new Error('"'Concurrent writes lost a book');
await Promise.all(created.map(book => fetch("'`${base}/api/books/${book.id}`,{method:'"'DELETE'})));
console.log('Invalid input and concurrent writes passed.');
